//! A fixed-capacity cache that evicts the least recently used entry.

use std::borrow::Borrow;
use std::collections::HashMap;
use std::hash::Hash;

/// Upper bound on the number of slots reserved up front, so a huge capacity
/// does not allocate memory that may never be used.
const MAX_INITIAL_CAPACITY: usize = 1 << 16;

/// Sentinel index meaning "no node".
const NIL: usize = usize::MAX;

struct Node<K, V> {
    key: K,
    value: V,
    prev: usize,
    next: usize,
}

/// A fixed-capacity LRU cache. All operations run in O(1) expected time.
///
/// Entries live in a slab of nodes linked into a doubly linked recency list
/// (head = least recently used, tail = most recently used); a hash map
/// indexes the slab by key. Freed slots are recycled through a free list.
pub struct LruCache<K, V> {
    capacity: usize,
    index: HashMap<K, usize>,
    nodes: Vec<Node<K, V>>,
    free: Vec<usize>,
    head: usize,
    tail: usize,
}

impl<K: Hash + Eq + Clone, V> LruCache<K, V> {
    /// Creates an empty cache holding at most `capacity` entries.
    ///
    /// # Panics
    ///
    /// Panics if `capacity` is zero.
    pub fn new(capacity: usize) -> Self {
        assert!(capacity >= 1, "capacity must be positive: {capacity}");
        let initial = capacity.min(MAX_INITIAL_CAPACITY);
        Self {
            capacity,
            index: HashMap::with_capacity(initial),
            nodes: Vec::with_capacity(initial),
            free: Vec::new(),
            head: NIL,
            tail: NIL,
        }
    }

    /// Inserts or overwrites a mapping, making the key the most recently used.
    /// Evicts the least recently used entry if the cache grows past capacity.
    pub fn put(&mut self, key: K, value: V) {
        if let Some(&slot) = self.index.get(&key) {
            self.nodes[slot].value = value;
            self.move_to_tail(slot);
            return;
        }

        let node = Node {
            key: key.clone(),
            value,
            prev: NIL,
            next: NIL,
        };
        let slot = match self.free.pop() {
            Some(slot) => {
                self.nodes[slot] = node;
                slot
            }
            None => {
                self.nodes.push(node);
                self.nodes.len() - 1
            }
        };
        self.push_tail(slot);
        self.index.insert(key, slot);

        if self.index.len() > self.capacity {
            self.evict_head();
        }
    }

    /// Returns the value for the key, marking it most recently used, or
    /// `None` if absent.
    pub fn get<Q>(&mut self, key: &Q) -> Option<&V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let slot = *self.index.get(key)?;
        self.move_to_tail(slot);
        Some(&self.nodes[slot].value)
    }

    /// Removes the key, returning whether it was present.
    pub fn remove<Q>(&mut self, key: &Q) -> bool
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        match self.index.remove(key) {
            Some(slot) => {
                self.unlink(slot);
                self.free.push(slot);
                true
            }
            None => false,
        }
    }

    /// Returns the number of entries held.
    pub fn len(&self) -> usize {
        self.index.len()
    }

    /// Returns `true` if the cache holds no entries.
    #[allow(dead_code)]
    pub fn is_empty(&self) -> bool {
        self.index.is_empty()
    }

    fn evict_head(&mut self) {
        let slot = self.head;
        debug_assert_ne!(slot, NIL, "evicting from an empty list");
        self.unlink(slot);
        self.index.remove(&self.nodes[slot].key);
        self.free.push(slot);
    }

    fn move_to_tail(&mut self, slot: usize) {
        if self.tail != slot {
            self.unlink(slot);
            self.push_tail(slot);
        }
    }

    fn push_tail(&mut self, slot: usize) {
        let node = &mut self.nodes[slot];
        node.prev = self.tail;
        node.next = NIL;
        match self.tail {
            NIL => self.head = slot,
            tail => self.nodes[tail].next = slot,
        }
        self.tail = slot;
    }

    fn unlink(&mut self, slot: usize) {
        let Node { prev, next, .. } = self.nodes[slot];
        match prev {
            NIL => self.head = next,
            prev => self.nodes[prev].next = next,
        }
        match next {
            NIL => self.tail = prev,
            next => self.nodes[next].prev = prev,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::LruCache;

    #[test]
    fn evicts_least_recently_used() {
        let mut cache = LruCache::new(2);
        cache.put("a", 1);
        cache.put("b", 2);
        assert_eq!(cache.get("a"), Some(&1));
        cache.put("c", 3);
        assert_eq!(cache.get("b"), None);
        assert_eq!(cache.len(), 2);
    }

    #[test]
    fn overwrite_refreshes_recency() {
        let mut cache = LruCache::new(2);
        cache.put("a", 1);
        cache.put("b", 2);
        cache.put("a", 9);
        cache.put("c", 3);
        assert_eq!(cache.get("a"), Some(&9));
        assert_eq!(cache.get("b"), None);
        assert_eq!(cache.get("c"), Some(&3));
    }

    #[test]
    fn remove_reports_presence_and_recycles_slots() {
        let mut cache = LruCache::new(3);
        cache.put("x", 1);
        assert!(cache.remove("x"));
        assert!(!cache.remove("x"));
        assert!(cache.is_empty());
        cache.put("y", 2);
        cache.put("z", 3);
        assert_eq!(cache.get("y"), Some(&2));
        assert_eq!(cache.len(), 2);
    }

    #[test]
    fn capacity_one() {
        let mut cache = LruCache::new(1);
        cache.put("a", 1);
        cache.put("b", 2);
        assert_eq!(cache.get("a"), None);
        assert_eq!(cache.get("b"), Some(&2));
        assert_eq!(cache.len(), 1);
    }
}

//! Reads LRU cache commands from standard input and writes results to
//! standard output. See SPEC.md for the protocol.

mod lru_cache;

use std::io::{self, BufWriter, Read, Write};
use std::process::ExitCode;

use lru_cache::LruCache;

type Cache = LruCache<Box<[u8]>, Box<[u8]>>;

fn main() -> ExitCode {
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(err) => {
            eprintln!("lru: {err}");
            ExitCode::FAILURE
        }
    }
}

fn run() -> io::Result<()> {
    let mut input = Vec::new();
    io::stdin().lock().read_to_end(&mut input)?;
    let mut out = BufWriter::with_capacity(1 << 16, io::stdout().lock());
    process(&input, &mut out)?;
    out.flush()
}

/// Executes every command in `input` against a cache sized by the header line.
fn process(input: &[u8], out: &mut impl Write) -> io::Result<()> {
    let mut lines = Lines::new(input);
    let Some(header) = lines.next() else {
        return Ok(());
    };
    let capacity = parse_capacity(header)?;
    let mut cache = Cache::new(capacity);
    for line in lines {
        execute(&mut cache, line, out)?;
    }
    Ok(())
}

fn parse_capacity(header: &[u8]) -> io::Result<usize> {
    let invalid = || io::Error::new(io::ErrorKind::InvalidData, "invalid capacity");
    let text = std::str::from_utf8(header.trim_ascii()).map_err(|_| invalid())?;
    match text.parse::<i32>() {
        Ok(n) if n >= 1 => Ok(n as usize),
        _ => Err(invalid()),
    }
}

fn execute(cache: &mut Cache, line: &[u8], out: &mut impl Write) -> io::Result<()> {
    let (command, args) = match line.iter().position(|&b| b == b' ') {
        Some(i) => (&line[..i], Some(&line[i + 1..])),
        None => (line, None),
    };
    match (command, args) {
        (b"SET", Some(args)) => {
            if let Some(i) = args.iter().position(|&b| b == b' ') {
                cache.put(args[..i].into(), args[i + 1..].into());
            }
        }
        (b"GET", Some(key)) => {
            let value = cache.get(key).map_or(&b"NULL"[..], |v| v);
            write_line(out, value)?;
        }
        (b"DEL", Some(key)) => {
            write_line(out, if cache.remove(key) { b"1" } else { b"0" })?;
        }
        (b"SIZE", _) => writeln!(out, "{}", cache.len())?,
        // Blank, malformed or unrecognised lines are ignored.
        _ => {}
    }
    Ok(())
}

fn write_line(out: &mut impl Write, text: &[u8]) -> io::Result<()> {
    out.write_all(text)?;
    out.write_all(b"\n")
}

/// Splits input into lines terminated by `\n`, `\r` or `\r\n`; the final line
/// may lack a terminator.
struct Lines<'a> {
    rest: &'a [u8],
}

impl<'a> Lines<'a> {
    fn new(input: &'a [u8]) -> Self {
        Self { rest: input }
    }
}

impl<'a> Iterator for Lines<'a> {
    type Item = &'a [u8];

    fn next(&mut self) -> Option<&'a [u8]> {
        if self.rest.is_empty() {
            return None;
        }
        let Some(end) = self.rest.iter().position(|&b| b == b'\n' || b == b'\r') else {
            return Some(std::mem::take(&mut self.rest));
        };
        let line = &self.rest[..end];
        let skip = if self.rest[end..].starts_with(b"\r\n") { 2 } else { 1 };
        self.rest = &self.rest[end + skip..];
        Some(line)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn run_str(input: &str) -> String {
        let mut out = Vec::new();
        process(input.as_bytes(), &mut out).unwrap();
        String::from_utf8(out).unwrap()
    }

    #[test]
    fn spec_example() {
        let input = "2\nSET a 1\nSET b 2\nGET a\nSET c 3\nGET b\nSIZE\n";
        assert_eq!(run_str(input), "1\nNULL\n2\n");
    }

    #[test]
    fn handles_crlf_and_missing_final_newline() {
        assert_eq!(run_str("1\r\nSET a 1\r\nGET a"), "1\n");
    }

    #[test]
    fn ignores_malformed_lines() {
        assert_eq!(run_str("2\n\nSET a\nGET\nDEL\nFOO\nSIZE\n"), "0\n");
    }
}
